import java.util.*;
import java.io.*;

public class CF552C {
  public static int maxPower, base;
  public static HashSet<Long> powersSet;
  public static void main(String[] args) throws Exception {
    Scanner scanner = new Scanner(System.in);
    PrintWriter writer = new PrintWriter(System.out);

    base = scanner.nextInt();
    long target = scanner.nextLong();

    int maxExponent = 0;
    for (int i = 0; base > 2 && i < 21; i++) {
      maxExponent = i;
      if (Math.pow(base, i) > 1e9) {
        break;
      }
    }

    powersSet = new HashSet<>();
    if (base > 2) generatePowers(0, 0, maxExponent);

    boolean found = false;
    if (base == 2) found = true;

    for (long val : powersSet) {
      if (val >= target && powersSet.contains(val - target)) {
        found = true;
        break;
      }
    }

    writer.println(found ? "YES" : "NO");
    writer.close();
  }

  static void generatePowers(int index, long sum, int maxExp) {
    if (index > maxExp) {
      powersSet.add(sum);
      return;
    }
    generatePowers(index + 1, sum + (long) Math.pow(base, index), maxExp);
    generatePowers(index + 1, sum, maxExp);
  }
}
